import Head from 'next/head';

const Page = ({ children }) => (
    <div className='page-root'>
      <Head>
        <title>Josh Marchello</title>
        <meta name="viewport" content="initial-scale=1.0, width=device-width" />
      </Head>
      <style jsx global>
        {`
          * {
            box-sizing: border-box;
            padding: 0;
            margin: 0;
          }

          html, body, .page-root {
            height: 100vh;
          }

          @font-face {
              font-family: "DejaVu Sans";
              src: url("/static/DejaVuSans.ttf");
          }
          @font-face {
              font-family: "DejaVu Sans";
              src: url("/static/DejaVuSans-Bold.ttf");
              font-weight: bold;
          }
          @font-face {
              font-family: "DejaVu Sans";
              src: url("/static/DejaVuSans-Oblique.ttf");
              font-style: italic, oblique;
          }
          @font-face {
              font-family: "DejaVu Sans";
              src: url("/static/DejaVuSans-BoldOblique.ttf");
              font-weight: bold;
              font-style: italic, oblique;
          }
        `}
      </style>
      { children }
  </div>
);

export default Page;



